mkuse!{use crate :: fmt :: { self , Display } ;}
mkuse!{use crate :: panic :: Location ;}
mkitem!{mkstruct!{# [doc = " A struct providing information about a panic."] # [doc = ""] # [doc = " A `PanicInfo` structure is passed to the panic handler defined by `#[panic_handler]`."] # [doc = ""] # [doc = " For the type used by the panic hook mechanism in `std`, see [`std::panic::PanicHookInfo`]."] # [doc = ""] # [doc = " [`std::panic::PanicHookInfo`]: ../../std/panic/struct.PanicHookInfo.html"] # [lang = "panic_info"] # [stable (feature = "panic_hooks" , since = "1.10.0")] # [derive (Debug)] pub struct PanicInfo < 'a > { message : & 'a fmt :: Arguments < 'a > , location : & 'a Location < 'a > , can_unwind : bool , force_no_backtrace : bool , }}}
mkitem!{mkstruct!{# [doc = " A message that was given to the `panic!()` macro."] # [doc = ""] # [doc = " The [`Display`] implementation of this type will format the message with the arguments"] # [doc = " that were given to the `panic!()` macro."] # [doc = ""] # [doc = " See [`PanicInfo::message`]."] # [stable (feature = "panic_info_message" , since = "1.81.0")] pub struct PanicMessage < 'a > { message : & 'a fmt :: Arguments < 'a > , }}}
mkitem!{mkimpl!{impl < 'a > PanicInfo < 'a > { # [inline] pub (crate) fn new (message : & 'a fmt :: Arguments < 'a > , location : & 'a Location < 'a > , can_unwind : bool , force_no_backtrace : bool ,) -> Self { PanicInfo { location , message , can_unwind , force_no_backtrace } } # [doc = " The message that was given to the `panic!` macro."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " The type returned by this method implements `Display`, so it can"] # [doc = " be passed directly to [`write!()`] and similar macros."] # [doc = ""] # [doc = " [`write!()`]: core::write"] # [doc = ""] # [doc = " ```ignore (no_std)"] # [doc = " #[panic_handler]"] # [doc = " fn panic_handler(panic_info: &PanicInfo<'_>) -> ! {"] # [doc = "     write!(DEBUG_OUTPUT, \"panicked: {}\", panic_info.message());"] # [doc = "     loop {}"] # [doc = " }"] # [doc = " ```"] # [must_use] # [stable (feature = "panic_info_message" , since = "1.81.0")] pub fn message (& self) -> PanicMessage < '_ > { PanicMessage { message : self . message } } # [doc = " Returns information about the location from which the panic originated,"] # [doc = " if available."] # [doc = ""] # [doc = " This method will currently always return [`Some`], but this may change"] # [doc = " in future versions."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```should_panic"] # [doc = " use std::panic;"] # [doc = ""] # [doc = " panic::set_hook(Box::new(|panic_info| {"] # [doc = "     if let Some(location) = panic_info.location() {"] # [doc = "         println!(\"panic occurred in file '{}' at line {}\","] # [doc = "             location.file(),"] # [doc = "             location.line(),"] # [doc = "         );"] # [doc = "     } else {"] # [doc = "         println!(\"panic occurred but can't get location information...\");"] # [doc = "     }"] # [doc = " }));"] # [doc = ""] # [doc = " panic!(\"Normal panic\");"] # [doc = " ```"] # [must_use] # [stable (feature = "panic_hooks" , since = "1.10.0")] pub fn location (& self) -> Option < & Location < '_ > > { Some (& self . location) } # [doc = " Returns the payload associated with the panic."] # [doc = ""] # [doc = " On this type, `core::panic::PanicInfo`, this method never returns anything useful."] # [doc = " It only exists because of compatibility with [`std::panic::PanicHookInfo`],"] # [doc = " which used to be the same type."] # [doc = ""] # [doc = " See [`std::panic::PanicHookInfo::payload`]."] # [doc = ""] # [doc = " [`std::panic::PanicHookInfo`]: ../../std/panic/struct.PanicHookInfo.html"] # [doc = " [`std::panic::PanicHookInfo::payload`]: ../../std/panic/struct.PanicHookInfo.html#method.payload"] # [deprecated (since = "1.81.0" , note = "this never returns anything useful")] # [stable (feature = "panic_hooks" , since = "1.10.0")] # [allow (deprecated , deprecated_in_future)] pub fn payload (& self) -> & (dyn crate :: any :: Any + Send) { struct NoPayload ; & NoPayload } # [doc = " Returns whether the panic handler is allowed to unwind the stack from"] # [doc = " the point where the panic occurred."] # [doc = ""] # [doc = " This is true for most kinds of panics with the exception of panics"] # [doc = " caused by trying to unwind out of a `Drop` implementation or a function"] # [doc = " whose ABI does not support unwinding."] # [doc = ""] # [doc = " It is safe for a panic handler to unwind even when this function returns"] # [doc = " false, however this will simply cause the panic handler to be called"] # [doc = " again."] # [must_use] # [unstable (feature = "panic_can_unwind" , issue = "92988")] pub fn can_unwind (& self) -> bool { self . can_unwind } # [unstable (feature = "panic_internals" , reason = "internal details of the implementation of the `panic!` and related macros" , issue = "none")] # [doc (hidden)] # [inline] pub fn force_no_backtrace (& self) -> bool { self . force_no_backtrace } }}}
mkitem!{mkimpl!{# [stable (feature = "panic_hook_display" , since = "1.26.0")] impl Display for PanicInfo < '_ > { fn fmt (& self , formatter : & mut fmt :: Formatter < '_ >) -> fmt :: Result { formatter . write_str ("panicked at ") ? ; self . location . fmt (formatter) ? ; formatter . write_str (":\n") ? ; formatter . write_fmt (* self . message) ? ; Ok (()) } }}}
mkitem!{mkimpl!{impl < 'a > PanicMessage < 'a > { # [doc = " Gets the formatted message, if it has no arguments to be formatted at runtime."] # [doc = ""] # [doc = " This can be used to avoid allocations in some cases."] # [doc = ""] # [doc = " # Guarantees"] # [doc = ""] # [doc = " For `panic!(\"just a literal\")`, this function is guaranteed to"] # [doc = " return `Some(\"just a literal\")`."] # [doc = ""] # [doc = " For most cases with placeholders, this function will return `None`."] # [doc = ""] # [doc = " See [`fmt::Arguments::as_str`] for details."] # [stable (feature = "panic_info_message" , since = "1.81.0")] # [rustc_const_stable (feature = "const_arguments_as_str" , since = "1.84.0")] # [must_use] # [inline] pub const fn as_str (& self) -> Option < & 'static str > { self . message . as_str () } }}}
mkitem!{mkimpl!{# [stable (feature = "panic_info_message" , since = "1.81.0")] impl Display for PanicMessage < '_ > { # [inline] fn fmt (& self , formatter : & mut fmt :: Formatter < '_ >) -> fmt :: Result { formatter . write_fmt (* self . message) } }}}
